/**
 * Production server entry.
 *
 * `dist/server/entry.mjs` (generated by `@astrojs/node`) auto-starts a server
 * that serves static files through `send`. Two problems with the stock entry:
 *
 *   1. With `send@1.x` the adapter's "immutable" cache header never reaches the
 *      response, so hashed assets were served with `Cache-Control: max-age=0`
 *      and revalidated on every navigation.
 *   2. Nothing compresses responses, so the ~180 KB CSS bundle and ~100 KB HTML
 *      pages are shipped as-is to clients that support gzip.
 *
 * This entry imports the generated handler (with autostart disabled), applies
 * the correct cache policy and security headers, rejects unsafe requests, rate
 * limits abusive clients, and gzips compressible responses.
 *
 * Usage: `bun server.mjs` (see Dockerfile CMD).
 */

process.env.ASTRO_NODE_AUTOSTART = "disabled";

import http from "node:http";
import fs from "node:fs";
import path from "node:path";
import { gzipSync } from "node:zlib";
import { securityHeaders, hstsHeader } from "./security-headers.mjs";
import { createRateLimiter } from "./rate-limit.mjs";

// Must be a dynamic import: static imports are evaluated before this module's
// body runs, which would let the generated entry start its own server.
const { handler } = await import("./dist/server/entry.mjs");

/** Files whose names contain a content hash: safe to cache for a year. */
const IMMUTABLE_PREFIX = "/_astro/";

/** Unhashed static assets (images, fonts, icons). */
const STATIC_ASSET_RE =
  /\.(webp|avif|png|jpe?g|gif|svg|ico|bmp|woff2?|ttf|otf|eot)$/i;

const IMMUTABLE_CACHE = "public, max-age=31536000, immutable";
const STATIC_CACHE = "public, max-age=604800, stale-while-revalidate=86400";
const PRERENDERED_CACHE = "public, max-age=300, stale-while-revalidate=86400";

const SECURITY_HEADERS = securityHeaders({ env: process.env, dev: false });
const limiter = createRateLimiter(process.env);

const COMPRESSIBLE_RE =
  /^(?:text\/|application\/(?:json|javascript|xml|xhtml\+xml|rss\+xml)|image\/svg\+xml)/i;

/** Below this, the gzip header costs more than it saves. */
const MIN_COMPRESS_BYTES = 1400;

/**
 * Largest accepted request body. No route accepts uploads or large forms, so
 * anything bigger is either abuse or a misconfiguration. Checked before the
 * handler runs because the adapter limit only applies once a body is read.
 */
const MAX_BODY_BYTES = Number(process.env.MAX_BODY_BYTES) || 256 * 1024;

/** Methods allowed by this site: it has no write endpoints at all. */
const READ_METHODS = new Set(["GET", "HEAD", "OPTIONS"]);

function bodyTooLarge(req) {
  const declared = Number(req.headers["content-length"]);
  if (Number.isFinite(declared) && declared > MAX_BODY_BYTES) return true;

  // Chunked requests: reject as soon as the first chunks exceed the limit.
  if (String(req.headers["transfer-encoding"] || "").toLowerCase().includes("chunked")) {
    let seen = 0;
    req.on("data", (chunk) => {
      seen += chunk.length;
      if (seen > MAX_BODY_BYTES && !req.destroyed) req.destroy();
    });
  }

  return false;
}

function cachePolicyFor(pathname) {
  if (pathname.startsWith(IMMUTABLE_PREFIX)) return IMMUTABLE_CACHE;
  if (STATIC_ASSET_RE.test(pathname)) return STATIC_CACHE;

  // Only cache HTML that Astro actually emitted during the build. This keeps
  // CMS-backed SSR routes (news, faculty, academics details) uncached while
  // allowing prerendered informational pages to be reused briefly by a CDN.
  const cleanPath = pathname.replace(/^\/+|\/+$/g, "");
  const htmlPath = path.join(
    process.cwd(),
    "dist",
    "client",
    cleanPath,
    "index.html",
  );
  if (fs.existsSync(htmlPath)) return PRERENDERED_CACHE;

  return null;
}

/**
 * Buffers a response so its headers can still be changed, then gzips it when
 * that will actually help. Streaming is traded for transfer size on purpose:
 * pages here are small and fully rendered before the first byte is useful.
 */
function compressResponse(req, res) {
  const acceptEncoding = String(req.headers["accept-encoding"] || "");
  const acceptsGzip = /\bgzip\b/i.test(acceptEncoding);
  const isBodyless = req.method === "HEAD" || req.method === "OPTIONS";

  const chunks = [];
  let statusCode = 200;
  let statusMessage = undefined;
  let headers = {};
  let headersCaptured = false;

  const originalWriteHead = res.writeHead.bind(res);

  res.writeHead = function (status, ...rest) {
    statusCode = status;
    let rawHeaders = {};

    if (typeof rest[0] === "string") {
      statusMessage = rest[0];
      rawHeaders = rest[1] || {};
    } else {
      rawHeaders = rest[0] || {};
    }

    // Node merges headers set with setHeader() into writeHead output.
    headers = { ...rawHeaders };
    for (const [key, value] of Object.entries(res.getHeaders())) {
      if (!(key in headers)) headers[key] = value;
    }

    headersCaptured = true;
    return res;
  };

  res.write = function (chunk, encoding, callback) {
    if (chunk) {
      chunks.push(
        Buffer.isBuffer(chunk)
          ? chunk
          : Buffer.from(chunk, typeof encoding === "string" ? encoding : undefined),
      );
    }
    if (typeof encoding === "function") encoding();
    else if (typeof callback === "function") callback();
    return true;
  };

  res.end = function (chunk, encoding, callback) {
    if (chunk && typeof chunk !== "function") {
      chunks.push(
        Buffer.isBuffer(chunk)
          ? chunk
          : Buffer.from(chunk, typeof encoding === "string" ? encoding : undefined),
      );
    }

    const body = chunk && typeof chunk === "function" ? null : Buffer.concat(chunks);
    const completionCallback =
      typeof chunk === "function" ? chunk : typeof encoding === "function" ? encoding : callback;

    // Static files are streamed by `send`, which sets headers with setHeader()
    // and never calls writeHead() explicitly — collect them here too.
    if (!headersCaptured) {
      for (const [key, value] of Object.entries(res.getHeaders())) {
        if (!(key in headers)) headers[key] = value;
      }
      headersCaptured = true;
    }

    const existingEncoding = headers["content-encoding"] || headers["Content-Encoding"];
    const contentType = String(headers["content-type"] || headers["Content-Type"] || "");
    const canCompress =
      acceptsGzip &&
      !isBodyless &&
      !existingEncoding &&
      statusCode === 200 &&
      body.length >= MIN_COMPRESS_BYTES &&
      COMPRESSIBLE_RE.test(contentType);

    const writeHeadNow = (finalStatus, finalHeaders) => {
      const message =
        typeof statusMessage === "string" && statusMessage.length > 0
          ? statusMessage
          : http.STATUS_CODES[finalStatus] || "";

      if (message) return originalWriteHead(finalStatus, message, finalHeaders);
      return originalWriteHead(finalStatus, finalHeaders);
    };

    if (canCompress) {
      const compressed = gzipSync(body, { level: 6 });
      const finalHeaders = { ...headers };
      delete finalHeaders["content-length"];
      delete finalHeaders["Content-Length"];
      finalHeaders["content-encoding"] = "gzip";
      finalHeaders["content-length"] = String(compressed.length);
      finalHeaders["vary"] = finalHeaders.vary ? `${finalHeaders.vary}, Accept-Encoding` : "Accept-Encoding";

      writeHeadNow(statusCode, finalHeaders);
      res.write = () => true;
      res.end = () => true;
      const result = http.ServerResponse.prototype.write.call(res, compressed);
      http.ServerResponse.prototype.end.call(res, undefined, completionCallback);
      return result;
    }

    if (headersCaptured) {
      // Body length is authoritative now that everything is buffered.
      const finalHeaders = { ...headers };
      if (!isBodyless) finalHeaders["content-length"] = String(body.length);
      writeHeadNow(statusCode, finalHeaders);
      res.write = () => true;
      res.end = () => true;
      return http.ServerResponse.prototype.end.call(res, isBodyless ? undefined : body, completionCallback);
    }

    return http.ServerResponse.prototype.end.call(res, body, completionCallback);
  };

  return res;
}

function isSecureRequest(req) {
  const proto = String(req.headers["x-forwarded-proto"] || "")
    .split(",")[0]
    .trim()
    .toLowerCase();
  return proto === "https" || Boolean(req.socket?.encrypted);
}

const server = http.createServer((req, res) => {
  const pathname = (req.url || "/").split("?")[0].split("#")[0];
  const policy = cachePolicyFor(pathname);

  // Security headers must be set here as well: prerendered HTML and static
  // assets are served by the Node adapter without running Astro middleware.
  // Headers coming from the handler take precedence (Astro's `Response`
  // headers are merged first in `compressResponse`).
  for (const [name, value] of Object.entries(SECURITY_HEADERS)) {
    res.setHeader(name, value);
  }
  if (isSecureRequest(req)) {
    const hsts = hstsHeader(process.env);
    if (hsts) res.setHeader("Strict-Transport-Security", hsts);
  }

  if (policy) {
    try {
      res.setHeader("Cache-Control", policy);
    } catch {
      // Response already started; nothing to do.
    }
  }

  // Rate limit before rendering: SSR pages trigger CMS calls, so this is the
  // cheapest place to stop floods and scrapers.
  const limited = limiter.check(req, pathname);
  if (limited) {
    const body = "Too Many Requests";
    res.writeHead(429, {
      "Content-Type": "text/plain; charset=utf-8",
      "Retry-After": String(limited.retryAfter),
      "Cache-Control": "no-store",
      "X-RateLimit-Limit": String(limited.limit),
      "X-RateLimit-Remaining": "0",
      "X-Robots-Tag": "noindex, nofollow",
    });
    res.end(body);
    return;
  }

  // No route accepts writes (no forms, actions or uploads): reject unsafe
  // methods outright instead of buffering a body nobody will read.
  if (!READ_METHODS.has(req.method || "GET")) {
    res.writeHead(405, {
      "Content-Type": "text/plain; charset=utf-8",
      "Allow": "GET, HEAD, OPTIONS",
      "Connection": "close",
      "Cache-Control": "no-store",
      "X-Robots-Tag": "noindex, nofollow",
    });
    res.end("Method Not Allowed");
    return;
  }

  if (bodyTooLarge(req)) {
    res.writeHead(413, {
      "Content-Type": "text/plain; charset=utf-8",
      "Connection": "close",
      "Cache-Control": "no-store",
      "X-Robots-Tag": "noindex, nofollow",
    });
    res.end("Payload Too Large");
    return;
  }
  compressResponse(req, res);
  handler(req, res);
});

const port = Number(process.env.PORT) || 3000;
const host = process.env.HOST || "0.0.0.0";

server.listen(port, host, () => {
  console.log(`[server] listening on http://${host}:${port}`);
});

for (const signal of ["SIGINT", "SIGTERM"]) {
  process.on(signal, () => {
    server.close(() => process.exit(0));
  });
}
